SELECT COUNT(1)
FROM doctor
WHERE hospital_id = #{hospitalId}
  AND dept_id = #{departmentId}
  AND status = 'ENABLED'
  AND deleted_at IS NULL

SELECT EXISTS (
    SELECT 1
    FROM schedule
    WHERE doctor_id = #{doctorId}
      AND schedule_date = #{date}
      AND status = 'PUBLISHED'
      AND deleted_at IS NULL
)
